<template>
 <view class="lh-scene-canvas" :class="{'lh-scene-still':reduced}" :data-scene-key="scene.key" :data-zone="zone.id" :data-scene-revision="scene.revision" :data-scene-element="scene.element" @tap="emit('ground',$event)">
  <view class="lh-scene-ambient" aria-hidden="true"/>
  <image v-for="node in zone.nodes" :key="node.id" class="lh-scene-node" :class="{'lh-node-react':targetId===node.id&&activeFx!=='none'}" :style="rectStyle(node.rect,node.layer==='floor'?0:node.layer==='architecture'?1:node.layer==='foreground'?150:node.depth)" :src="sceneAsset(node.assetId)" v-show="!failedAssets.has(node.assetId)" @error="failedAssets.add(node.assetId);emit('assetError',node.assetId)" mode="scaleToFill" aria-hidden="true"/>
  <image v-if="windmillNode" class="lh-scene-node lh-windmill-rotor" :class="{'lh-rotor-turn':activeFx==='wind_chime'&&!reduced}" :style="rectStyle(windmillNode.rect,4)" :src="sceneAsset('v6-prop-windmill-rotor')" mode="scaleToFill" aria-hidden="true"/>
  <view v-for="item in placed" :key="item.id" class="lh-scene-object" :class="{'lh-node-react':targetId===item.id&&activeFx!=='none'}" :style="rectStyle(item.rect,item.depth)" :data-furniture="item.owned.furnitureId"><image class="lh-scene-object-image" :src="furnitureVisual(item.owned.furnitureId,scene.element,'stage',2)" mode="aspectFit" aria-hidden="true"/><WPActionTile v-if="interactive" class="lh-scene-object-button" :aria-label="furnitureRegistry[item.owned.furnitureId].name+'，点击互动或管理'" @click.stop="emit('object',item.id,item.owned.instanceId)"/></view>
  <view v-if="targetId==='water-interaction-5'&&activeFx==='ripple'" class="lh-scene-reflection" :style="{left:(actorPosition.x-.15)*100+'%',top:actorPosition.y*100+'%'}" aria-hidden="true"><SceneActorArt :element="scene.element" :form="form" :pose="actorPose" :cosmetic="cosmetic" :cosmetics="cosmetics" :allow-q="allowQ"/></view><view class="lh-scene-shadow" :class="{'lh-shadow-jump':actorMotion==='jump','lh-shadow-float':actorMotion==='float'}" :style="{left:actorPosition.x*100+'%',top:actorPosition.y*100+'%',width:actorWidth*.5*100+'%',zIndex:actualPose==='sleep'?(contactSlot?.depth??70)+1:2,transitionDuration:(reduced?0:duration)+'ms'}" aria-hidden="true"/>
  <view class="lh-scene-actor" :class="'lh-motion-'+actorMotion" :style="actorStyle" :data-motion="actorMotion"><WPActionTile v-if="interactive" class="lh-scene-actor-button" :aria-label="'与'+petInfo[scene.element].name+'互动'" @click.stop="emit('actor')"><SceneActorArt :element="scene.element" :form="form" :pose="actorPose" :cosmetic="cosmetic" :cosmetics="cosmetics" :allow-q="allowQ" @appearance="appearance"/></WPActionTile><SceneActorArt v-else :element="scene.element" :form="form" :pose="actorPose" :cosmetic="cosmetic" :cosmetics="cosmetics" :allow-q="allowQ" @appearance="appearance"/></view>
  <image v-if="scene.revision===3&&actualPose==='sleep'&&contactSlot" class="lh-scene-node lh-contact-mask" :style="rectStyle(contactSlot.rect,130)" :src="sceneAsset('v6-bed-front-'+scene.element)" mode="aspectFit" aria-hidden="true"/>
  <view v-if="activeFx==='watering'||activeFx==='harvest'" class="lh-scene-prop-response" :class="'lh-prop-'+activeFx" :style="{left:(actorPosition.x+.035)*100+'%',top:(actorPosition.y-.26)*100+'%'}" aria-hidden="true"><image :src="sceneAsset(activeFx==='watering'?'v6-prop-watering-can':'v6-prop-harvest-basket')" mode="aspectFit"/><view v-if="activeFx==='watering'" class="lh-water-stream"/></view>
  <view v-if="activeFx!=='none'" class="lh-scene-fx" :class="['lh-fx-'+activeFx,{'lh-fx-still':reduced}]" :style="{left:actorPosition.x*100+'%',top:actorPosition.y*100+'%'}" :data-effect="activeFx" aria-hidden="true"><view v-for="i in 5" :key="i" :style="{'--i':i}"/><image v-if="activeFx==='book_shift'" :src="sceneAsset('fixture-books')" mode="aspectFit"/></view>
  <view v-if="preview" class="lh-scene-placement"><WPActionTile v-for="slot in candidates" :key="slot.id" class="lh-scene-slot" :selected="preview.slotId===slot.id" :style="rectStyle(slot.rect,180)" :aria-label="'放在'+slotDefinitions[slot.id].name" @click.stop="emit('slot',slot.id)"><text>{{slotDefinitions[slot.id].name}}</text></WPActionTile><image v-if="selectedSlot" class="lh-scene-ghost" :style="rectStyle(selectedSlot.rect,170)" :src="furnitureVisual(preview.furnitureId,scene.element,'stage',2)" mode="aspectFit" aria-hidden="true"/></view>
 </view>
</template>
<script setup lang="ts">
import {computed,ref} from 'vue'
import {petInfo} from '../../../../packages/pet_engine'
import {compatibleSlots,furnitureRegistry,slotDefinitions} from '../../../services/pet-lifehouse/HouseRegistry'
import {sceneAsset,type SceneActorSource} from '../../../services/pet-lifehouse/SceneVisualPack'
import {placedSceneSlots,type SceneDefinition,type SceneZone} from '../../../services/pet-lifehouse/SceneConfig'
import {furnitureVisual} from '../../../services/pet-lifehouse/SceneVisualRegistry'
import type {ScenePoint,SceneRect} from '../../../services/pet-lifehouse/SceneGeometry'
import type {SceneFx,SceneMotion} from '../../../services/pet-lifehouse/SceneActionController'
import type {ElementHouse,SlotId} from '../../../services/pet-lifehouse/types'
import type {PetForm} from '../../../services/pet-growth'
import SceneActorArt from './SceneActorArt.vue'
import WPActionTile from '../../button/WPActionTile.vue'
const props=withDefaults(defineProps<{scene:SceneDefinition;zone:SceneZone;house:ElementHouse;form:PetForm;cosmetic?:string|null;cosmetics?:readonly string[];actorPosition:ScenePoint;actorMotion?:SceneMotion;actorPose?:'idle'|'sit'|'sleep';activeFx?:SceneFx;targetId?:string|null;duration?:number;reduced?:boolean;interactive?:boolean;allowQ?:boolean;preview?:{furnitureId:string;slotId?:SlotId}|null}>(),{actorMotion:'idle',actorPose:'idle',activeFx:'none',duration:0,interactive:false,allowQ:true})
const emit=defineEmits<{ground:[event:any];object:[slot:SlotId,instance:string];actor:[];slot:[slot:SlotId];appearance:[source:SceneActorSource];assetError:[id:string]}>(),failedAssets=ref(new Set<string>()),support=ref({x:.5,y:.96})
const placed=computed(()=>placedSceneSlots(props.scene,props.house,props.zone.id)),candidates=computed(()=>{const item=props.preview&&furnitureRegistry[props.preview.furnitureId];return item?props.scene.slots.filter(s=>s.zoneId===props.zone.id&&compatibleSlots(item,props.house.level).includes(s.id)):[]}),selectedSlot=computed(()=>candidates.value.find(s=>s.id===props.preview?.slotId))
const windmillNode=computed(()=>props.zone.nodes.find(n=>n.id==='v6-windmill'))
const actualPose=ref<'idle'|'sit'|'sleep'>('idle'),contactSlot=computed(()=>placed.value.find(s=>s.id===props.targetId))
const actorWidth=computed(()=>actualPose.value==='sleep'?(placed.value.find(s=>s.id===props.targetId)?.rect.width??.27)*.82:props.scene.actorWidth??.30)
const actorStyle=computed(()=>({left:(props.actorPosition.x-actorWidth.value*support.value.x)*100+'%',top:(props.actorPosition.y-actorWidth.value*2*support.value.y)*100+'%',width:actorWidth.value*100+'%',height:actorWidth.value*200+'%',zIndex:actualPose.value==='sleep'?(contactSlot.value?.depth??70)+2:Math.round(props.actorPosition.y*100),transitionDuration:(props.reduced?0:props.duration)+'ms'}))
function rectStyle(r:SceneRect,z:number){return{left:r.x*100+'%',top:r.y*100+'%',width:r.width*100+'%',height:r.height*100+'%',zIndex:z}}
function appearance(source:SceneActorSource){support.value=source.support;actualPose.value=source.pose??'idle';emit('appearance',source)}
</script>
<style scoped>
.lh-scene-canvas{position:relative;width:100%;aspect-ratio:1.5;isolation:isolate;overflow:hidden;background:linear-gradient(180deg,var(--lh-bg),var(--lh-tint));border-radius:22px;touch-action:pan-y}.lh-scene-node,.lh-scene-object,.lh-scene-actor,.lh-scene-slot,.lh-scene-ghost{position:absolute}.lh-scene-node{pointer-events:none}.lh-scene-object{min-width:0;min-height:0}.lh-scene-object-image{width:100%;height:100%}.lh-scene-object-button.lh-scene-object-button,.lh-scene-actor-button.lh-scene-actor-button{width:100%;height:100%;min-height:0;padding:0;background:transparent!important;border:0;border-radius:20%;display:block}.lh-scene-object-button image{width:100%;height:100%}.lh-scene-actor{transition-property:left,top;transition-timing-function:linear;pointer-events:auto}.lh-scene-actor-button{overflow:visible!important}.lh-scene-shadow{position:absolute;z-index:2;width:18%;height:3%;border-radius:50%;background:rgba(61,93,99,.17);filter:blur(4px);transform:translate(-50%,-50%);pointer-events:none}.lh-scene-placement{position:absolute;inset:0;pointer-events:none;z-index:180}.lh-scene-slot.lh-scene-slot{pointer-events:auto;min-height:44px;font-size:12px;padding:3px;background:rgba(244,252,249,.7);border:2px dashed #477B83;color:#314F63;z-index:180;border-radius:14px}.lh-scene-ghost{opacity:.7;pointer-events:none}.lh-scene-ambient{position:absolute;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(ellipse at 15% 20%,rgba(255,255,255,.8),transparent 50%)}.lh-motion-float>.lh-scene-actor-button,.lh-motion-float>.lh-scene-actor-art{animation:lh-q-float 1.1s ease-in-out infinite}.lh-motion-jump>.lh-scene-actor-button{animation:lh-q-jump .55s ease-out 2}.lh-motion-hide_reveal>.lh-scene-actor-button{animation:lh-q-peek 1.1s ease-in-out}.lh-node-react{animation:lh-object-wiggle .5s ease-in-out 2}.lh-scene-fx{position:absolute;z-index:160;width:24%;height:24%;transform:translate(-50%,-70%);pointer-events:none}.lh-scene-fx view{position:absolute;left:calc(var(--i)*16%);top:calc(70% - var(--i)*10%);width:9px;height:9px;border-radius:50%;background:#FFF1AC;animation:lh-q-particle 1.1s ease-out infinite;animation-delay:calc(var(--i)*.05s);box-shadow:0 0 5px #fff}.lh-fx-ripple view{width:65%;height:25%;left:18%;top:70%;border:2px solid #8ACDE9;background:transparent;animation:lh-q-ripple 1.1s ease-out infinite}.lh-fx-bubble view{background:rgba(210,242,255,.55);border:1px solid #fff;width:15%;height:22%}.lh-fx-doodle_trace view{background:#F5B9D0}.lh-fx-leaf_sway view{background:#A1D5AA;border-radius:0 90%}.lh-fx-wind_chime view{background:#B8DEF3}.lh-fx-book_shift image{width:50%;height:70%;position:absolute;left:40%;top:0;animation:lh-object-wiggle .45s ease-in-out 2}.lh-fx-still view{animation:none}.lh-fx-still view:nth-child(n+3){display:none}@keyframes lh-q-float{50%{transform:translateY(-4px)}}@keyframes lh-q-jump{50%{transform:translateY(-12px)}}@keyframes lh-q-peek{40%,60%{transform:translateX(-8px) rotate(-3deg)}}@keyframes lh-object-wiggle{25%{transform:rotate(-2deg)}75%{transform:rotate(2deg)}}@keyframes lh-q-particle{0%{opacity:0;transform:translateY(6px) scale(.6)}40%{opacity:1}100%{opacity:0;transform:translateY(-15px) scale(1.1)}}@keyframes lh-sort-block{from{transform:translate(calc(var(--i)*-3px),-12px)}to{transform:translate(0,0)}}@keyframes lh-q-ripple{from{opacity:1;transform:scale(.35)}to{opacity:0;transform:scale(1.2)}}.lh-scene-reflection{position:absolute;z-index:2;width:30%;height:60%;transform:scaleY(-1);transform-origin:50% 0;opacity:.15;pointer-events:none;mask-image:linear-gradient(transparent 65%,#000 100%)}.lh-fx-object_sort view{border-radius:3px;width:12px;height:12px;background:#BCE8D8;animation:lh-sort-block 1s ease-out}.lh-fx-cushion_squish view{border-radius:50%;background:#FFF4C5}.lh-scene-still *{animation:none!important;transition:none!important}
</style>

<style scoped>.lh-scene-shadow{transition-property:left,top;transition-timing-function:linear}.lh-shadow-jump{animation:lh-contact-jump .55s ease-out 2}.lh-shadow-float{opacity:.65}@keyframes lh-contact-jump{50%{opacity:.4;transform:translate(-50%,-50%) scale(.7)}}.lh-scene-still .lh-scene-shadow{animation:none!important}</style>

<style scoped>.lh-scene-object-button.lh-scene-object-button{position:absolute;left:50%;top:50%;width:max(100%,44px);height:max(100%,44px);min-width:44px;min-height:44px;transform:translate(-50%,-50%)!important}.lh-scene-object>.lh-scene-object-image{position:absolute;inset:0;pointer-events:none}</style>

<style scoped>.lh-windmill-rotor{transform-origin:50.6% 34.3%}.lh-rotor-turn{animation:lh-windmill-turn 1.6s linear infinite}.lh-scene-prop-response{position:absolute;width:17%;height:25.5%;z-index:120;pointer-events:none}.lh-scene-prop-response>image{width:100%;height:100%}.lh-prop-watering>image{transform:rotate(24deg);transform-origin:35% 70%}.lh-water-stream{position:absolute;left:89%;top:68%;height:35%;width:4%;border-left:2px dotted #7dbfe1;transform:rotate(-18deg);opacity:.85}.lh-fx-watering>view,.lh-fx-harvest>view{display:none}@keyframes lh-windmill-turn{to{transform:rotate(360deg)}}.lh-scene-still .lh-rotor-turn{animation:none}</style>

<style scoped>.lh-fx-cushion_squish{width:18%;height:5%;transform:translate(-50%,-50%);z-index:129}.lh-fx-cushion_squish>view{left:10%;top:20%;width:80%;height:50%;background:transparent;border:1px solid #fff0c1;box-shadow:none;animation:lh-q-ripple 1.4s ease-out}.lh-fx-cushion_squish>view:nth-child(n+2){display:none}</style>
